-- Fakt kartochkalarining ruscha matni — 22-partiya: mumtoz shoirlar.
-- Sakkokiy, Lutfiy, Atoyi, Durbek, Sayfi Saroyi, Turdi Farog'iy,
-- So'fi Olloyor, Gulxaniy.
--
-- IZOH. Ichida keltirilgan she'riy parchalar (2223, 2293, 2166) ma'no
-- bo'yicha o'girildi: aruz vazni va qofiyasi boshqa tilda saqlanmaydi,
-- shuning uchun bayt mazmuni nasrda berildi.

-- ===== Sakkokiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Саккаки и что известно о его настоящем имени?', fact_ru = 'Ни год моего рождения, ни моё настоящее имя в истории не сохранились — народ знает меня под именем Саккаки. Я жил и творил в XV веке в городе Самарканде.' WHERE id = 2290;
UPDATE fact_cards SET topic_ru = 'Время моей жизни', question_ru = 'В какую пору и где творил Саккаки?', fact_ru = 'Я жил и творил в городе Самарканде в правление Халиля Султана (1405–1409) и Мирзо Улугбека. Всё моё творчество прошло в эту тимуридскую пору.' WHERE id = 2291;
UPDATE fact_cards SET topic_ru = 'Начало жанра касыды', question_ru = 'Какому жанру положил начало Саккаки и кому посвящал свои касыды?', fact_ru = 'Я один из поэтов, положивших начало жанру касыды в узбекской литературе. Свои касыды я посвящал Ходже Мухаммаду Порсо, Халилю Султану, Улугбеку и Арслану Ходже Тархану.' WHERE id = 2292;
UPDATE fact_cards SET topic_ru = 'Моя касыда Улугбеку', question_ru = 'Как Саккаки описал Улугбека в своей касыде?', fact_ru = 'В одной из своих касыд я возвеличил Мирзо Улугбека как милостивого к народу правителя, просветителя и великого учёного. Гордясь тем, что творю на тюркском языке, я написал так: «Годы должен кружить небосвод, чтобы привести в свои руки такого тюркского поэта, как я, и такого мудрого шаха, как ты».' WHERE id = 2293;
UPDATE fact_cards SET topic_ru = 'Темы моих газелей', question_ru = 'Какие темы воспевал Саккаки в своих газелях?', fact_ru = 'В своих газелях я воспевал любовь человека, его мечты и чаяния, его боль и печаль, а также красоты природы. В стихах я проводил мысли о справедливости против невежества и неразумия.' WHERE id = 2294;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Какова судьба дивана Саккаки?', fact_ru = 'Написанные мной за жизнь газели и касыды были собраны и сведены в диван.' WHERE id = 2295;
UPDATE fact_cards SET topic_ru = 'Моё влияние на литературу', question_ru = 'Какое влияние оказал Саккаки на узбекскую литературу?', fact_ru = 'Я обогатил узбекскую светскую лирику и по содержанию, и по форме. Я творил в одну пору с такими поэтами, как Лутфи, Гадои и Атаи.' WHERE id = 2296;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Саккаки?', fact_ru = 'Год моей смерти, как и год рождения, в истории точно не сохранился. Моя жизнь прошла в XV веке, в городе Самарканде.' WHERE id = 2297;

-- ===== Lutfiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Лутфи?', fact_ru = 'Я родился в 1366 году. Большая часть моей жизни связана с городом Герат; иные же источники указывают моей родиной Ташкент.' WHERE id = 2219;
UPDATE fact_cards SET topic_ru = 'Мой титул «малик уль-калам»', question_ru = 'Каким титулом был возвеличен Лутфи?', fact_ru = 'Современники дали мне высокий титул «малик уль-калам», то есть «царь слова». Под этим именем меня чтили и поэты, и придворные вельможи.' WHERE id = 2220;
UPDATE fact_cards SET topic_ru = 'Моё творчество на тюркском и фарси', question_ru = 'На каких языках творил Лутфи?', fact_ru = 'Великую славу я снискал стихами на родном тюркском языке. И на персидском я заставил многих признать мой поэтический дар.' WHERE id = 2221;
UPDATE fact_cards SET topic_ru = 'Мой тюркский диван', question_ru = 'Какие стихи вошли в диван Лутфи?', fact_ru = 'Собрав свои стихи, я составил тюркский диван: в нём есть газели, рубаи, туюги и кыта. Стихи моего дивана насчитывают более 2774 бейтов, из них 2086 бейтов — газели.' WHERE id = 2222;
UPDATE fact_cards SET topic_ru = 'Ты — моя любовь', question_ru = 'Какие строки Лутфи знамениты?', fact_ru = 'Вот мои знаменитые строки: «Ты — моя любовь, хочешь верь, хочешь не верь, / В крови моё сердце, хочешь верь, хочешь не верь». Эти строки многие в народе выучили наизусть.' WHERE id = 2223;
UPDATE fact_cards SET topic_ru = 'Вопрос о «Гуль и Наврузе»', question_ru = 'Чьим произведением считался дастан «Гуль и Навруз»?', fact_ru = 'Этот дастан долгое время приписывался моему имени, однако позднейшие исследования указали, что он принадлежит Хайдару Хорезми. То есть «Гуль и Навруз» — не моё произведение.' WHERE id = 2224;
UPDATE fact_cards SET topic_ru = 'Навои и моя школа', question_ru = 'Как относился Навои к Лутфи?', fact_ru = 'И перевалив за девяносто лет, я не переставал слагать стихи. В последние годы моей жизни вступивший на поприще творчества юный Алишер Навои учился в моей творческой школе. И поэт следующего поколения Захириддин Мухаммад Бабур черпал из моей поэзии.' WHERE id = 2225;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Лутфи?', fact_ru = 'Я скончался в 1465 году на 99-м году жизни; источники пишут, что последним моим пристанищем был город Герат. А стихи мои остались жить среди тюркских народов.' WHERE id = 2226;

-- ===== Atoyi =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Атаи?', fact_ru = 'Год моего рождения в истории точно не сохранился — сведений об этом в источниках нет. Я жил и творил в XV веке, моя жизнь связана с городом Балх.' WHERE id = 2122;
UPDATE fact_cards SET topic_ru = 'Мой род', question_ru = 'Чьим потомком был Атаи?', fact_ru = 'Я принадлежу к дому великого шейха Ахмада Яссави: я потомок его брата Ибрахима-ата и считаюсь одним из детей Исмаила-ата.' WHERE id = 2123;
UPDATE fact_cards SET topic_ru = 'Города, где я жил', question_ru = 'В каких городах жил Атаи и какие науки постиг?', fact_ru = 'Я жил в городах Самарканд, Бухара и Балх. Основательно изучив тюркскую, персидскую и арабскую словесность, я творил на тюркском и персидском языках.' WHERE id = 2124;
UPDATE fact_cards SET topic_ru = 'О дворе Улугбека', question_ru = 'Кто сообщил о пребывании Атаи при дворе Улугбека?', fact_ru = 'По некоторым источникам, я был и среди поэтов двора Мирзо Улугбека — этот вопрос среди учёных остаётся спорным.' WHERE id = 2125;
UPDATE fact_cards SET topic_ru = 'Мои газели и моя манера', question_ru = 'Какие стихи писал Атаи и какова была его манера?', fact_ru = 'Я поэт-газелист — в своих газелях я воспевал любовь. Стихи я писал главным образом размером рамаль в арузе и использовал в них народные речения и пословицы. Оттого что строки мои коротки, а слова просты, мои газели превратились в народные песни.' WHERE id = 2126;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Сколько газелей в диване Атаи и где он хранится?', fact_ru = 'Свои газели я собрал в диван. В моём диване сведены 260 моих газелей.' WHERE id = 2127;
UPDATE fact_cards SET topic_ru = 'Моя слава', question_ru = 'Что сказал об Атаи Алишер Навои?', fact_ru = 'Мои стихи снискали в моё время большую славу среди тюрков. Современники знали меня как человека дервишеского нрава, скромного и благонравного.' WHERE id = 2128;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Атаи?', fact_ru = 'И год моей смерти точно не известен — я скончался в XV веке. Грядущим поколениям в наследство остался мой диван, где собраны мои газели.' WHERE id = 2129;

-- ===== Durbek =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Дурбек?', fact_ru = 'Год моего рождения точно не известен — я появился на свет в конце XIV века. Вся моя жизнь и всё моё творчество связаны с древним городом Балх.' WHERE id = 2163;
UPDATE fact_cards SET topic_ru = 'Балх — мой родной город', question_ru = 'В каком городе жил и творил Дурбек?', fact_ru = 'Я жил и творил в древнем городе Балх. В своём дастане я отразил виды городов и селений, тамошние события и обычаи.' WHERE id = 2164;
UPDATE fact_cards SET topic_ru = 'Мой дастан «Юсуф и Зулейха»', question_ru = 'Когда Дурбек написал дастан «Юсуф и Зулейха»?', fact_ru = 'В 1409 году я написал свой дастан «Юсуф и Зулейха». В нём я изложил стихами на узбекском языке знаменитое на Востоке сказание о Юсуфе и Зулейхе.' WHERE id = 2165;
UPDATE fact_cards SET topic_ru = 'Творчество на тюркском', question_ru = 'На каком языке написал свой дастан Дурбек?', fact_ru = 'Свой дастан я написал на тюркском — староузбекском языке. Об этом своём намерении я сказал в произведении строкой: «Твёрдо решив писать на тюркском языке».' WHERE id = 2166;
UPDATE fact_cards SET topic_ru = 'Описание осады Балха', question_ru = 'Какое историческое событие изображено в дастане Дурбека?', fact_ru = 'В своём дастане я изобразил осаду города Балх, муки и страдания народа от голода и жажды.' WHERE id = 2167;
UPDATE fact_cards SET topic_ru = 'Мой герой Юсуф', question_ru = 'Кто главный герой дастана Дурбека?', fact_ru = 'Главный герой моего дастана — Юсуф. Я показал его судьбу и его отношение к жизни в разных обстоятельствах.' WHERE id = 2168;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Дурбек?', fact_ru = 'Год моей смерти точно не известен. Я скончался в первой половине XV века.' WHERE id = 2169;

-- ===== Sayfi Saroyi =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Сайфи Сараи?', fact_ru = 'Я родился в 1321 году в селении Сарыкамыш Хорезмской области. Моё детство пришлось на пору монгольского завоевания, и потому мне пришлось покинуть родину.' WHERE id = 2298;
UPDATE fact_cards SET topic_ru = 'Моя скитальческая жизнь', question_ru = 'В каких городах и странах жил Сайфи Сараи?', fact_ru = 'Моя жизнь прошла в скитаниях: покинув родной Хорезм, я жил в городе Сарай в Золотой Орде, а затем в Египте и Турции.' WHERE id = 2299;
UPDATE fact_cards SET topic_ru = 'Мой труд «Гулистан бит-турки»', question_ru = 'Как Сайфи Сараи создал труд «Гулистан бит-турки»?', fact_ru = 'В 1391 году я переложил на тюркский язык знаменитый «Гулистан» Саади и создал полуоригинальный философско-нравственный труд под названием «Гулистан бит-турки». Эта моя книга состоит из восьми глав, и я добавил в неё новые рассказы, отражающие дух времени.' WHERE id = 2300;
UPDATE fact_cards SET topic_ru = 'Мысли моих произведений', question_ru = 'Какие мысли проводил Сайфи Сараи в своих произведениях?', fact_ru = 'В поучительных рассказах моей книги «Гулистан бит-турки» я возвеличивал такие достоинства, как справедливость, честность, верность и милосердие. А в стихах я воспевал любовь к родине, человечность, дружбу и любовь.' WHERE id = 2301;
UPDATE fact_cards SET topic_ru = '«Сухайль и Гульдурсун»', question_ru = 'Какие ещё произведения создал Сайфи Сараи?', fact_ru = 'Я написал дастан под названием «Сухайль и Гульдурсун», а также перевёл на тюркский язык произведение «Синдбаднаме».' WHERE id = 2302;
UPDATE fact_cards SET topic_ru = 'Моя поэзия', question_ru = 'В каких жанрах творил Сайфи Сараи?', fact_ru = 'Я лирический поэт, сочинитель касыд, эпический дастанчи и переводчик. В жанрах газели, касыды, кыта и рубаи я сложил более десяти стихотворений.' WHERE id = 2303;
UPDATE fact_cards SET topic_ru = 'Мои познания и языки', question_ru = 'Какие языки и науки знал Сайфи Сараи?', fact_ru = 'Я основательно овладел персидским и арабским языками, словесностью и историей, а также народными поэтическими преданиями. Эти познания и пригодились мне, когда я перекладывал труд Саади на тюркский язык.' WHERE id = 2304;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Сайфи Сараи?', fact_ru = 'Последние годы жизни я провёл в Египте и скончался в 1398 году в городе Александрия.' WHERE id = 2305;

-- ===== Turdi Farog'iy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Где и когда родился Турди Фароги?', fact_ru = 'Я родился в XVII веке в городе Бухаре, год моего рождения точно не известен. Моё настоящее имя — Турди, а в персидско-таджикских стихах я пользовался псевдонимом Фароги.' WHERE id = 1983;
UPDATE fact_cards SET topic_ru = 'Моя учёба в медресе', question_ru = 'Где учился Турди и на каких языках творил?', fact_ru = 'Я учился в бухарских медресе. Свои стихи я свободно писал и на узбекском, и на персидском языках.' WHERE id = 1984;
UPDATE fact_cards SET topic_ru = 'Род юз и двор', question_ru = 'Из какого рода был Турди и при ком он служил при дворе?', fact_ru = 'Я из рода юз. При Абдулазизхане я был одним из придворных сановников и видных политических деятелей рода юз. Когда на престол взошёл Субханкулихан, меня отстранили от двора.' WHERE id = 1985;
UPDATE fact_cards SET topic_ru = 'Народное восстание', question_ru = 'В каком восстании участвовал Турди и куда он ушёл потом?', fact_ru = 'В 1685–86 годах я деятельно участвовал в народном восстании против Аштарханидов. Когда восстание было подавлено, мне пришлось уйти сперва в Джизак, а затем в Худжанд.' WHERE id = 1986;
UPDATE fact_cards SET topic_ru = 'Моё поэтическое наследие', question_ru = 'Сколько поэтического наследия осталось от Турди?', fact_ru = 'До нас дошли 18 моих стихотворений: 12 газелей, 5 мухаммасов и один фард — всего 434 строки. Свои газели я писал весьма сжато, в 3–5 бейтов.' WHERE id = 1987;
UPDATE fact_cards SET topic_ru = 'Моя знаменитая сатира', question_ru = 'О ком написал Турди сатиру в 1691 году?', fact_ru = 'В 1691 году я написал свою знаменитую сатиру в 165 строк о Субханкулихане. В ней я резко высмеял хана и его порядки.' WHERE id = 1988;
UPDATE fact_cards SET topic_ru = 'Моё обращение к бекам', question_ru = 'В каком стихотворении Турди призывал беков к согласию и равенству?', fact_ru = 'В стихотворении, начинающемся словами «Беки с тесной душою», я обратился к бекам и призвал их быть широкими нравом, держаться взаимного согласия и не унижать друг друга по родовым признакам.' WHERE id = 1989;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Турди Фароги?', fact_ru = 'После подавления восстания последние годы жизни я провёл в Худжанде в нужде и душевном унынии. Я скончался в 1699/1700 году в Худжанде.' WHERE id = 1990;

-- ===== So'fi Olloyor =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Суфи Аллаяр?', fact_ru = 'Я появился на свет в 1644 году в селении Минглар, относившемся к Каттакурганскому бекству.' WHERE id = 1975;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где учился Суфи Аллаяр?', fact_ru = 'Я учился в школе шейхов и в обители джуйбарских шейхов в Бухаре. Я основательно изучил арабский и персидский языки.' WHERE id = 1976;
UPDATE fact_cards SET topic_ru = 'Моя служба в таможне', question_ru = 'Кто назначил Суфи Аллаяра главой таможенной управы?', fact_ru = 'Бухарский хан Абдулазизхан назначил меня главой таможенной управы. Но с этой должности я вскоре ушёл в отставку.' WHERE id = 1977;
UPDATE fact_cards SET topic_ru = 'Мой путь суфизма', question_ru = 'К кому пошёл в ученики Суфи Аллаяр, оставив должность?', fact_ru = 'Оставив должность, я пошёл в ученики к знаменитому шейху своего времени Наврузу. Стремясь к совершенству на пути суфизма, я вырос в валиуллаха.' WHERE id = 1978;
UPDATE fact_cards SET topic_ru = 'Мой труд «Сабот уль-оджизин»', question_ru = 'Какой знаменитый труд написал Суфи Аллаяр на тюркском языке?', fact_ru = 'По просьбе друзей и близких я написал на тюркском языке книгу «Сабот уль-оджизин», то есть «Стойкость немощных». Я изложил её стихами на узбекском языке, несколько сократив свой труд «Маслак уль-муттакин».' WHERE id = 1979;
UPDATE fact_cards SET topic_ru = 'Мои персидские труды', question_ru = 'Каков самый крупный персоязычный труд Суфи Аллаяра и из скольких бейтов он состоит?', fact_ru = 'На персидском языке я написал книгу «Маслак уль-муттакин» («Путь богобоязненных») — она состоит из 12 тысяч бейтов и 135 глав. Создал я и труды «Мурод уль-орифин» и «Махзан уль-мутиин».' WHERE id = 1980;
UPDATE fact_cards SET topic_ru = 'Мои другие тюркские труды', question_ru = 'Какие ещё труды создал Суфи Аллаяр на тюркском языке?', fact_ru = 'На тюркском языке я написал также книгу «Фавз ун-наджот» («Торжество спасения») и стихотворное произведение «Спор плодов».' WHERE id = 1981;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Суфи Аллаяр?', fact_ru = 'Я скончался в 1724 году в Денау. После моей смерти мои труды широко разошлись и за пределами Туркестана — от Кашгара до Поволжья и Приуралья, в Астраханском, Булгарском и Оренбургском краях.' WHERE id = 1982;

-- ===== Gulxaniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Гульхани?', fact_ru = 'Я родился примерно в конце XVIII века в Коканде. Моё настоящее имя — Мухаммад Шариф, а Гульхани — мой псевдоним.' WHERE id = 1991;
UPDATE fact_cards SET topic_ru = 'Причина моего псевдонима', question_ru = 'Откуда взялся псевдоним Гульхани?', fact_ru = 'В юности я работал истопником в бане — голахом. Мой псевдоним «Гульхани» и произошёл от этого труда у огня-гульхана.' WHERE id = 1992;
UPDATE fact_cards SET topic_ru = 'Моя служба при ханском дворе', question_ru = 'Какую службу нёс Гульхани при дворе кокандских ханов?', fact_ru = 'С 1801 по 1810 год я служил в рядах нукеров кокандского хана Амира Алимхана. После смерти Алимхана Амир Умархан (Амирий) привлёк меня в круг придворных поэтов.' WHERE id = 1993;
UPDATE fact_cards SET topic_ru = 'Мой труд «Зарбульмасаль»', question_ru = 'Чем знаменит труд Гульхани «Зарбульмасаль»?', fact_ru = 'Самый знаменитый мой труд — написанный прозой «Зарбульмасаль». В нём я употребил около 400 народных пословиц, садж — рифмованную прозу, притчи и предания.' WHERE id = 1994;
UPDATE fact_cards SET topic_ru = 'Сова и филин', question_ru = 'Похождения каких птиц изображены в «Зарбульмасале»?', fact_ru = 'В «Зарбульмасале» я изобразил в иносказательной, острой сатирической форме похождения Совы и Филина, ставших сватами. В образах птиц я подверг критике общественную жизнь моего времени.' WHERE id = 1995;
UPDATE fact_cards SET topic_ru = 'Мои стихи и мои языки', question_ru = 'На каких языках и какие стихи писал Гульхани?', fact_ru = 'Я творил на узбекском и таджикском языках. В своих газелях я воспевал любовь, разлуку, весну и картины подлинной жизни; сохранились такие мои стихи, как «Мой палец», «Грудь моя как лоно тюльпана».' WHERE id = 1996;
UPDATE fact_cards SET topic_ru = 'Моё имя в тазкира', question_ru = 'В каких тазкира сохранились сведения о Гульхани?', fact_ru = 'Мой современник Фазли Наманганий привёл сведения обо мне в тазкире «Маджмуаи шоирон».' WHERE id = 1997;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Гульхани?', fact_ru = 'О последних годах моей жизни в источниках точных сведений не сохранилось. Я скончался примерно в 20-е годы XIX века.' WHERE id = 1998;
